package org.apache.commons.math.stat.correlation;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.distribution.TDistribution;
import org.apache.commons.math.distribution.TDistributionImpl;
import org.apache.commons.math.linear.BlockRealMatrix;
import org.apache.commons.math.linear.RealMatrix;
import org.apache.commons.math.stat.regression.SimpleRegression;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.stat.correlation.PearsonsCorrelation;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for PearsonsCorrelation.getCorrelationPValues()
 */
public class PearsonsCorrelation_getCorrelationPValues_TriageGen1Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testGetCorrelationPValues_PerfectCorrelation() {
        double[][] data = {
            {1.0, 2.0, 3.0},
            {1.0, 2.0, 3.0},
            {1.0, 2.0, 3.0}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        int nVars = 3;
        Assert.assertEquals(nVars, pValues.getRowDimension());
        Assert.assertEquals(nVars, pValues.getColumnDimension());

        // Diagonal should be 0
        Assert.assertEquals(0.0, pValues.getEntry(0, 0), EPSILON);
        Assert.assertEquals(0.0, pValues.getEntry(1, 1), EPSILON);
        Assert.assertEquals(0.0, pValues.getEntry(2, 2), EPSILON);

        // Off-diagonal for perfect correlation (r=1) should be 0
        // Note: In the implementation, 1-r*r becomes 0, leading to division by zero.
        // Math.sqrt(NaN) or Infinity results in t being Infinity.
        // 1 - cumulativeProbability(Infinity) is 0.
        Assert.assertEquals(0.0, pValues.getEntry(0, 1), EPSILON);
        Assert.assertEquals(0.0, pValues.getEntry(1, 0), EPSILON);
    }

    @Test
    public void testGetCorrelationPValues_StandardCase() {
        // Data designed to produce predictable correlation
        double[][] data = {
            {1.0, 2.0, 3.0},
            {2.0, 4.0, 6.0},
            {3.0, 1.0, 5.0}
        };
        // Row 0 and Row 1 are perfectly correlated (r=1.0)
        // Row 2 is different
        PearsonsCorrelation correlation = new PearsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        // Check dimensions
        Assert.assertEquals(3, pValues.getRowDimension());

        // Check diagonal
        for (int i = 0; i < 3; i++) {
            Assert.assertEquals(0.0, pValues.getEntry(i, i), EPSILON);
        }

        // Check that p-value for identical rows is 0
        Assert.assertEquals(0.0, pValues.getEntry(0, 1), EPSILON);

        // Check that p-values are within valid probability range [0, 1]
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                double val = pValues.getEntry(i, j);
                Assert.assertTrue("P-value should be >= 0", val >= 0.0);
                Assert.assertTrue("P-value should be <= 1", val <= 1.0);
            }
        }
    }

    @Test
    public void testGetCorrelationPValues_SmallDataset() {
        // Minimum observations for T-distribution (n-2 > 0) is n=3
        double[][] data = {
            {1.0, 5.0},
            {2.0, 3.0},
            {3.0, 1.0}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        RealMatrix pValues = correlation.getCorrelationPValues();

        Assert.assertEquals(2, pValues.getRowDimension());
        Assert.assertEquals(0.0, pValues.getEntry(0, 0), EPSILON);
        Assert.assertEquals(0.0, pValues.getEntry(1, 1), EPSILON);
        // For n=3, r=-1, p-value should be 0
        Assert.assertTrue(pValues.getEntry(0, 1) < 1.0);
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testGetCorrelationPValues_InsufficientObservations() {
        // n-2 must be > 0 for T-distribution. If n=2, n-2=0, which is invalid for T-distribution.
        double[][] data = {
            {1.0, 2.0},
            {3.0, 4.0}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data);
        // This should trigger an exception in TDistributionImpl due to degrees of freedom <= 0
        correlation.getCorrelationPValues();
    }

    @Test
    public void testGetCorrelationPValues_NegativeCorrelation() {
        double[][] data = {
            {1.0, 2.0, 3.0},
            {3.0, 2.0, 1.0},
            {1.0, 1.0, 1.0} // Constant row might cause issues, let's use non-constant
        };
        // Use specific data to ensure r is negative
        double[][] data2 = {
            {1, 2, 3},
            {3, 2, 1},
            {2, 1, 2}
        };
        PearsonsCorrelation correlation = new PearsonsCorrelation(data2);
        RealMatrix pValues = correlation.getCorrelationPValues();

        // r between row 0 and 1 is -1.0. P-value should be 0.
        Assert.assertEquals(0.0, pValues.getEntry(0, 1), EPSILON);
    }
}

/**
 * Helper to handle naming if necessary, though the requirement asked for one specific class.
 * Using a local alias to ensure the test compiles against the provided signature.
 */
class PearsCorrelation extends PearsonsCorrelation {
    public PearsCorrelation(double[][] data) {
        super(data);
    }
}
